style.css:
@-moz-document domain("roblox.com") {
body {
        background-image: url("https://pic.vjshi.com/2023-03-02/899326ea50084c80ad30a335462dd2d1/online/main.jpg?x-oss-process=style/w342_h192_center");
        background-size: cover;
        background-attachment: fixed;
        background-repeat: no-repeat;
    }

    /* Estilos adicionales para mejorar la legibilidad */
    #navbar, .navbar, #header {
        background-color: rgba(0, 0, 0, 0.5); /* Fondo semitransparente oscuro */
    }

    .container, .content {
        background-color: rgba(255, 255, 255, 0.8); /* Fondo semitransparente claro */
    }

    h1, h2, h3, h4, h5, h6 {
        color: #2a623d; /* Color de los encabezados */
    }

    a {
        color: #2a623d; /* Color de los enlaces */
    }
}
